    @EventHandler( payloadType=UpdateCandidateEvent.class )
    public void handle( UpdateCandidateEvent event) {
    	LOGGER.info("handling UpdateCandidateEvent - " + event );
    	
	    Candidate entity = new Candidate();
            entity.setCandidateId( event.getCandidateId() );
            entity.setName( event.getName() );
            entity.setEmail( event.getEmail() );
            entity.setPhone( event.getPhone() );
            entity.setApplications( event.getApplications() );
            entity.setInterviews( event.getInterviews() );
            entity.setOffers( event.getOffers() );
            entity.setDocuments( event.getDocuments() );
            entity.setSource( event.getSource() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCandidate( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCandidate( entity );        
    }
    
