    /**
     * Method to retrieve the Candidate via an CandidatePrimaryKey.
     * @param 	id Long
     * @return 	Candidate
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Candidate handle( FindCandidateQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCandidateId() );
    }
    
    /**
     * Method to retrieve a collection of all Candidates
     *
     * @param	query	FindAllCandidateQuery 
     * @return 	List<Candidate> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Candidate> handle( FindAllCandidateQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCandidate,
 * but only if the id matches
 *
 * @param		entity	Candidate
 */
	protected void emitFindCandidate( Candidate entity ) {
		LOGGER.info("handling emitFindCandidate" );
		
	    queryUpdateEmitter.emit(FindCandidateQuery.class,
	                            query -> query.getFilter().getCandidateId().equals(entity.getCandidateId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCandidate
	 * 
	 * @param		entity	Candidate
	 */
	protected void emitFindAllCandidate( Candidate entity ) {
		LOGGER.info("handling emitFindAllCandidate" );
		
	    queryUpdateEmitter.emit(FindAllCandidateQuery.class,
	                            query -> true,
	                            entity);
	}

